mapper.select:
SELECT id, source_channel AS channel, package_name, app_version, source_event_time,
       COALESCE(source_event_time, ingest_time) AS occurred_at, province_code, city_code
FROM t_feedback_source
WHERE id > #{query.afterId}
  AND source_channel IN
  #{channel}
AND COALESCE(source_event_time, ingest_time) >= #{query.from}
AND COALESCE(source_event_time, ingest_time) <= #{query.to}

    AND (province_code IN
    #{region}
    OR city_code IN
    #{region})

AND package_name = #{query.packageName}
AND app_version = #{query.appVersion}
ORDER BY id LIMIT #{query.limit}
